const fs = require('fs');
const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
const src = html.match(/<script>([\s\S]*)<\/script>/)[1];
const m = { exports: {} };
new Function('module', src)(m);
const { createScene, DEFAULTS, STEP } = m.exports;

const g0 = DEFAULTS.gravity;

function energy(sc, g) {
  let e = 0;
  for (const b of sc.world.bodies) {
    if (b.invM === 0) continue;
    const I = b.invI > 0 ? 1 / b.invI : 0;
    e += 0.5 * b.mass * (b.vx * b.vx + b.vy * b.vy) + 0.5 * I * b.w * b.w + b.mass * g * b.y;
  }
  return e;
}

function run(over, seconds) {
  const P = Object.assign({}, DEFAULTS, over);
  const sc = createScene(P), w = sc.world, car = sc.car;
  const n = Math.round(seconds / STEP);
  let nan = false, maxV = 0, maxPen = 0, eHit = null, eMaxAfter = 0, pxHit = null, pxMaxAfter = -1e9;
  let impactSpeed = null, settledAt = null, calm = 0;
  let sumMs = 0, maxMs = 0;
  for (let i = 0; i < n; i++) {
    const vBefore = car.vx;
    const t0 = process.hrtime.bigint();
    w.step();
    const ms = Number(process.hrtime.bigint() - t0) / 1e6;
    sumMs += ms; if (ms > maxMs) maxMs = ms;
    let mv = 0, mw = 0, px = 0;
    for (const b of w.bodies) {
      if (!isFinite(b.x) || !isFinite(b.y) || !isFinite(b.c) || !isFinite(b.vx) || !isFinite(b.vy)) nan = true;
      const v = Math.hypot(b.vx, b.vy); if (v > maxV) maxV = v; if (v > mv) mv = v;
      const a = Math.abs(b.w); if (a > mw) mw = a;
      px += b.mass * b.vx;
    }
    if (nan) break;
    for (const c of w.contacts) for (let k = 0; k < c.n; k++) if (-c.pts[k].sep > maxPen) maxPen = -c.pts[k].sep;
    if (w.hit) {
      if (impactSpeed === null) { impactSpeed = vBefore; eHit = energy(sc, P.gravity); pxHit = px; }
      const e = energy(sc, P.gravity);
      if (e > eMaxAfter) eMaxAfter = e;
      if (px > pxMaxAfter) pxMaxAfter = px;
      if (settledAt === null) { calm = (mv < 0.05 && mw < 0.1) ? calm + STEP : 0; if (calm >= 1.2) settledAt = w.time - w.hitTime; }
    }
  }
  let disp = 0, maxX = 0, standing = 0;
  for (const b of sc.bricks) {
    const d = Math.abs(b.x - b.x0) > 0.12 || Math.abs(b.y - b.y0) > 0.12 || Math.abs(Math.atan2(b.s, b.c)) > 0.12;
    if (d) disp++; else standing++;
    maxX = Math.max(maxX, b.x);
  }
  const carNose = car.x + P.carW / 2;
  return {
    P: over, impactV: impactSpeed && +impactSpeed.toFixed(2), hit: w.hit, hitT: +w.hitTime.toFixed(3),
    carX: +car.x.toFixed(2), carV: +car.vx.toFixed(3), carAng: +Math.atan2(car.s, car.c).toFixed(3),
    disp, of: sc.bricks.length, maxX: +maxX.toFixed(1), wallRight: +sc.wallRight.toFixed(1),
    maxV: +maxV.toFixed(1), maxPen: +maxPen.toFixed(4), nan,
    EgainRatio: eHit ? +(eMaxAfter / eHit).toFixed(4) : null,
    pxGain: pxHit ? +((pxMaxAfter - pxHit) / Math.abs(pxHit)).toFixed(4) : null,
    settledAfter: settledAt && +settledAt.toFixed(1),
    msAvg: +(sumMs / n).toFixed(3), msMax: +maxMs.toFixed(2),
    sig: sc.bricks.slice(0, 4).map(b => b.x.toFixed(9)).join(',') + '|' + car.x.toFixed(9)
  };
}

const mode = process.argv[2] || 'default';
if (mode === 'rest') {
  for (const cfg of [{}, { cols: 24, rows: 16, layers: 5, brickMass: 12 }, { cols: 4, rows: 3, layers: 1, brickMass: 0.5 },
    { cols: 24, rows: 16, layers: 1, brickMass: 0.5 }, { cols: 24, rows: 16, layers: 5, brickMass: 0.5, brickFriction: 0.05 },
    { gravity: 24 }, { gravity: 1.62, brickRestitution: 0.9 }, { brickW: 0.8, brickH: 0.15 }, { brickW: 0.3, brickH: 0.4 }]) {
    const P = Object.assign({}, DEFAULTS, cfg);
    const sc = createScene(P);
    sc.car.tow = false; sc.world.towTarget = 0; sc.car.x = -50;
    for (let i = 0; i < 720; i++) sc.world.step();
    let dx = 0, dy = 0, a = 0, mv = 0;
    for (const b of sc.bricks) {
      dx = Math.max(dx, Math.abs(b.x - b.x0)); dy = Math.max(dy, Math.abs(b.y - b.y0));
      a = Math.max(a, Math.abs(Math.atan2(b.s, b.c))); mv = Math.max(mv, Math.hypot(b.vx, b.vy));
    }
    console.log('REST', JSON.stringify(cfg), 'dx', dx.toFixed(4), 'dy', dy.toFixed(4), 'ang', a.toFixed(4), 'v', mv.toFixed(4));
  }
} else if (mode === 'default') {
  const a = run({}, 25), b = run({}, 25);
  console.log('DEFAULT', JSON.stringify(a));
  console.log('DETERMINISTIC', a.sig === b.sig, a.sig === b.sig ? '' : a.sig + ' vs ' + b.sig);
} else if (mode === 'sweep') {
  const cfgs = [
    { speed: 5 }, { speed: 10 }, { speed: 45 },
    { speed: 5, brickMass: 12 }, { speed: 45, brickMass: 12 },
    { speed: 5, brickMass: 12, layers: 5, cols: 24, rows: 16 }, { speed: 45, brickMass: 12, layers: 5, cols: 24, rows: 16 },
    { speed: 45, brickMass: 0.5, layers: 1, cols: 4, rows: 3 }, { speed: 5, brickMass: 0.5, layers: 1, cols: 4, rows: 3 },
    { speed: 45, cols: 24, rows: 16, layers: 1, brickMass: 0.5 }, { speed: 22, cols: 24, rows: 16, layers: 5 },
    { speed: 30, brickMass: 12 }, { speed: 45, carMass: 300, brickMass: 12, layers: 5 }, { speed: 45, carMass: 5000, brickMass: 0.5, layers: 1 },
    { speed: 45, gravity: 1.62 }, { speed: 45, gravity: 24 }, { speed: 45, brickRestitution: 0.9 }, { speed: 45, brickFriction: 0.05 }
  ];
  for (const c of cfgs) console.log(JSON.stringify(run(c, 20)));
}

