const page = await browser.getPage("crash");
const errors = [];
page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
page.on("console", (m) => { if (m.type() === "error" || m.type() === "warning") errors.push(m.type() + ": " + m.text()); });
await page.setViewportSize({ width: 1440, height: 860 });
await page.goto("file:///private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/cursor-continuation-lnu1tmfw/app/index.html");
await page.waitForTimeout(600);
console.log("title:", await page.title());
console.log("h1:", await page.locator("h1").allInnerTexts());
const init = await page.evaluate(() => {
  const c = window.__crash;
  return { P: c.P, bricks: c.scene.bricks.length, carX: c.scene.car.x, running: c.S.running };
});
console.log("initial:", JSON.stringify(init));
await saveScreenshot(await page.screenshot(), "ui_initial.png");
await page.click("#btnTest");
const marks = [0.4, 0.9, 1.6, 3.0];
let shot = 0;
for (let i = 0; i < 40 && shot < marks.length; i++) {
  await page.waitForTimeout(150);
  const s = await page.evaluate(() => ({ t: window.__crash.scene.world.time, hit: window.__crash.scene.world.hit, fin: window.__crash.S.finished }));
  if (s.hit && (s.t - (await page.evaluate(() => window.__crash.scene.world.hitTime))) >= marks[shot] - 0.05) {
    await saveScreenshot(await page.screenshot(), "ui_run_" + shot + ".png");
    shot++;
  }
  if (s.fin) break;
}
await page.waitForTimeout(1500);
