page.on("console", (m) => { if (m.type() === "error") errors.push(m.type() + ": " + m.text()); });
await page.setViewportSize({ width: 1440, height: 860 });
await page.goto("file:///private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/cursor-continuation-lnu1tmfw/app/index.html");
await page.waitForTimeout(500);

async function runToEnd(maxMs) {
  await page.click("#btnTest");
  const t0 = Date.now();
  while (Date.now() - t0 < maxMs) {
    await page.waitForTimeout(250);
    if (await page.evaluate(() => window.__crash.S.finished)) break;
  }
  return await page.evaluate(() => {
    const s = window.__crash.scene;
    return { fin: window.__crash.S.finished, t: +s.world.time.toFixed(3), sig: s.bricks.slice(0, 5).map(b => b.x.toFixed(9)).join(",") + "|" + s.car.x.toFixed(9), toast: document.querySelector("#toast").innerText };
  });
}

// determinism across two full runs in the browser
const r1 = await runToEnd(60000);
const r2 = await runToEnd(60000);
console.log("run1:", JSON.stringify(r1));
console.log("run2:", JSON.stringify(r2));
console.log("deterministic:", r1.sig === r2.sig && r1.t === r2.t);

// Reset returns to the initial layout
await page.click("#btnReset");
const afterReset = await page.evaluate(() => ({ t: window.__crash.scene.world.time, carX: window.__crash.scene.car.x, b0: window.__crash.scene.bricks[0].x, running: window.__crash.S.running }));
console.log("after reset:", JSON.stringify(afterReset));

// Changing one setting must not change the others
const before = await page.evaluate(() => JSON.stringify(window.__crash.P));
await page.fill("#num-speed", "35");
await page.press("#num-speed", "Enter");
await page.waitForTimeout(100);
const after = await page.evaluate(() => JSON.parse(JSON.stringify(window.__crash.P)));
const b = JSON.parse(before);
const changed = Object.keys(after).filter((k) => after[k] !== b[k]);
console.log("changed keys after editing speed:", JSON.stringify(changed), "speed=", after.speed);
await page.click("#btnDefaults");
console.log("defaults restored:", await page.evaluate(() => JSON.stringify(window.__crash.P)) === before);

// clamp check
await page.fill("#num-speed", "999");
await page.press("#num-speed", "Enter");
console.log("speed clamped:", await page.evaluate(() => window.__crash.P.speed));
await page.click("#btnDefaults");

// Extremes: each main parameter min and max, run for ~1.5s and look for NaN/errors
const extremes = [
  { speed: 5 }, { speed: 45 }, { cols: 4 }, { cols: 24 }, { rows: 3 }, { rows: 16 }, { layers: 1 }, { layers: 5 }, { brickMass: 0.5 }, { brickMass: 12 },
  { speed: 45, cols: 24, rows: 16, layers: 5, brickMass: 12 }, { speed: 45, cols: 24, rows: 16, layers: 1, brickMass: 0.5 }, { speed: 5, cols: 4, rows: 3, layers: 1, brickMass: 12 }
];
for (const ex of extremes) {
  await page.click("#btnDefaults");
  for (const k of Object.keys(ex)) { await page.fill("#num-" + k, String(ex[k])); await page.press("#num-" + k, "Enter"); }
  await page.click("#btnTest");
  await page.waitForTimeout(2200);
  const st = await page.evaluate(() => {
    const s = window.__crash.scene; let bad = 0;
    for (const bd of s.world.bodies) if (!isFinite(bd.x) || !isFinite(bd.y) || !isFinite(bd.c)) bad++;
    return { bad, t: +s.world.time.toFixed(2), hit: s.world.hit, bricks: s.bricks.length, cam: [+window.__crash.cam.x.toFixed(1), +window.__crash.cam.s.toFixed(1)] };
  });
  console.log("extreme", JSON.stringify(ex), JSON.stringify(st));
}
await page.click("#btnDefaults");
console.log("errors:", JSON.stringify(errors));

