    this.n = 0; this.nx = 0; this.ny = 0; this.friction = 0; this.restitution = 0;
    this.stale = false; this.isNew = true; this.pts = [new Pt(), new Pt()];
    const ka = this.A.kind, kb = this.B.kind;
    this.isStatic = this.A.invM === 0 || this.B.invM === 0;
    this.carBrick = (ka === K_CAR && kb === K_BRICK) || (ka === K_BRICK && kb === K_CAR);
