/* =====================================================================
   SCENE CONSTRUCTION
   ===================================================================== */
function polyProps(p) {
  let A = 0, cx = 0, cy = 0, I = 0;
  const n = p.length / 2;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n, x1 = p[2 * i], y1 = p[2 * i + 1], x2 = p[2 * j], y2 = p[2 * j + 1];
    const cr = x1 * y2 - x2 * y1;
    A += cr / 2; cx += (x1 + x2) * cr / 6; cy += (y1 + y2) * cr / 6;
    I += cr * (x1 * x1 + x1 * x2 + x2 * x2 + y1 * y1 + y1 * y2 + y2 * y2) / 12;
  }
  return { a: A, cx: cx / A, cy: cy / A, i0: I };
}

function buildCar(world, P) {
  const sx = P.carW / 4.2, sy = P.carH / 1.45;
  const sc = (a) => a.map((v, i) => (i & 1 ? v * sy : v * sx));
  const chassis = sc([-2.10, 0.28, 2.10, 0.28, 2.10, 0.66, 1.85, 0.82, -1.90, 0.84, -2.10, 0.70]);
  const cabin = sc([-1.30, 0.80, 0.90, 0.80, 0.30, 1.45, -0.85, 1.45]);
  const wr = 0.32 * Math.min(sx, sy);
  const wheels = [[-1.32 * sx, wr], [1.32 * sx, wr]];
  const p1 = polyProps(chassis), p2 = polyProps(cabin);
  const rho = P.carMass / (p1.a + p2.a), m1 = p1.a * rho, m2 = p2.a * rho, M = m1 + m2;
  const comx = (m1 * p1.cx + m2 * p2.cx) / M, comy = (m1 * p1.cy + m2 * p2.cy) / M;
  const inertia = (p1.i0 + p2.i0) * rho - M * (comx * comx + comy * comy);
  const b = new Body(K_CAR, P.carW / 2 + comx, comy + 0.0005, M, inertia);
  b.linDamp = 0; b.angDamp = 0;
  const loc = (a) => a.map((v, i) => v - (i & 1 ? comy : comx));
  const fr = P.groundFriction, e = 0.1;
  b.addPoly(loc(chassis), fr, e);
  b.addPoly(loc(cabin), fr, e);
  for (const w of wheels) b.addCircle(w[0] - comx, w[1] - comy, wr, fr, e).wheel = true;
  b.tow = true; b.braking = false; b.spin = 0;
  b.info = { sx, sy, comx, comy, wr, wheels };
  world.add(b); world.car = b;
  world.towTarget = P.speed;
  world.towAccel = P.speed * P.speed / (2 * (RUN_UP - 0.15));
  return b;
}

function createScene(P) {
  nextBodyId = 1; nextShapeId = 1;
  const world = new World(P.gravity);
  world.groundShape.friction = P.groundFriction;
  const car = buildCar(world, P);
  const bw = P.brickW, bh = P.brickH, hw = bw / 2, hh = bh / 2;
  const x0 = P.carW + RUN_UP;
  const mass = P.brickMass * P.layers, inertia = mass * (bw * bw + bh * bh) / 12;
  const bricks = [];
  for (let r = 0; r < P.rows; r++) {
    for (let c = 0; c < P.cols; c++) {
      const x = x0 + bw * (c + 0.5 + (r & 1 ? STAGGER : 0)), y = bh * (r + 0.5);
      const b = new Body(K_BRICK, x, y, mass, inertia);
      b.addPoly([-hw, -hh, hw, -hh, hw, hh, -hw, hh], P.brickFriction, P.brickRestitution);
      b.tint = (r * 7 + c * 13 + ((r * c) % 5)) % 6;
      bricks.push(b); world.add(b);
    }
  }
  const right = x0 + bw * (P.cols + STAGGER);
  return { world, car, bricks, wallX0: x0, wallRight: right, P: Object.assign({}, P) };
}

/* Node hook for headless testing */
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { createScene, DEFAULTS, STEP, World, RUN_UP };
}

/* =====================================================================
   PRESENTATION
   ===================================================================== */
function initApp() {
  const $ = (s) => document.querySelector(s);
  const canvas = $('#view'), ctx = canvas.getContext('2d'), stage = $('#stage');
  const P = Object.assign({}, DEFAULTS);
