  let W = 800, H = 600, dpr = 1, groundY = 450, simT = 0;
  const cam = { x: 0, s: 60 }, base = { x: 0, s: 60 };
  const shake = { amp: 0 };
  const dust = [], chips = [], skids = [];
  let rng = mulberry32(7), lastWheelX = [null, null];

  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
