  /* ---------- scene lifecycle ---------- */
  function build() {
    S.scene = createScene(P);
    S.running = false; S.finished = false; S.acc = 0; S.still = 0;
    dust.length = 0; chips.length = 0; skids.length = 0; shake.amp = 0; lastWheelX = [null, null];
    rng = mulberry32(20240607);
