    const fitX = (W - 24) / (right - left);
    const fitY = (groundY - 96) / (Math.max(P.rows * P.brickH, P.carH) + 1.3);
    base.s = Math.max(12, Math.min(P.scale, fitX, fitY));
    base.x = (left + right) / 2;
  }

  /* ---------- FX ---------- */
  function spawnImpact(ev) {
