      for (let i = 0; i < nd && dust.length < 700; i++) {
        const a = Math.PI * (0.15 + rng() * 0.7);
        dust.push({ x: ev.x + (rng() - 0.5) * 0.3, y: Math.max(0.05, ev.y) + rng() * 0.2, vx: Math.cos(a) * (0.5 + rng() * 2.5) * strength + ev.nx * 1.5,
          vy: Math.sin(a) * (0.6 + rng() * 2.2) * strength, r: 0.10 + rng() * 0.22 * strength, life: 0, max: 0.8 + rng() * 1.2, a: 0.32 + rng() * 0.2, g: 0 });
      }
    }
    if (v > 5) {
      const nc = Math.min(carHit ? 12 : 5, 2 + (v * 0.4) | 0);
      for (let i = 0; i < nc && chips.length < 500; i++) {
        const sp = (0.25 + rng() * 0.6) * v * 0.45, a = Math.atan2(ev.ny, ev.nx) + (rng() - 0.5) * 2.4;
        chips.push({ x: ev.x, y: Math.max(0.05, ev.y), vx: Math.cos(a) * sp + (carHit ? 3 : 0), vy: Math.abs(Math.sin(a)) * sp * 0.8 + 1,
          sz: 0.025 + rng() * 0.055, rot: rng() * 6.28, vr: (rng() - 0.5) * 24, life: 0, max: 2.2 + rng() * 2, tint: (rng() * 3) | 0 });
      }
    }
    if (carHit) shake.amp = Math.min(16, shake.amp + strength * 5.5);
    else if (v > 8) shake.amp = Math.min(16, shake.amp + strength * 0.9);
  }

  function updateFx(dt) {
    for (let i = dust.length - 1; i >= 0; i--) {
      const p = dust[i]; p.life += dt;
      if (p.life >= p.max) { dust[i] = dust[dust.length - 1]; dust.pop(); continue; }
      const d = Math.exp(-dt * 1.6);
      p.vx *= d; p.vy = p.vy * d + p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt; if (p.y < 0.02 && p.g === 0) { p.y = 0.02; p.vy = Math.abs(p.vy) * 0.2; }
      p.r += dt * 0.35;
    }
    for (let i = chips.length - 1; i >= 0; i--) {
      const p = chips[i]; p.life += dt;
      if (p.life >= p.max) { chips[i] = chips[chips.length - 1]; chips.pop(); continue; }
      p.vy -= 9.81 * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.rot += p.vr * dt;
      if (p.y < p.sz) { p.y = p.sz; p.vy *= -0.3; p.vx *= 0.6; p.vr *= 0.6; if (Math.abs(p.vy) < 0.4) p.vy = 0; }
    }
    shake.amp *= Math.exp(-dt * 5.5);
    const car = S.scene.car;
    if (S.running && car.braking && dust.length < 700) {
      const sp = Math.sqrt(car.vx * car.vx + car.vy * car.vy);
      if (sp > 2 && car.y < 1.6 * car.info.sy) {
        const cnt = dt * sp * 1.3; let n = Math.floor(cnt) + (rng() < cnt % 1 ? 1 : 0);
        for (; n > 0; n--) {
          const wh = car.info.wheels[(rng() * 2) | 0], x = car.x + car.c * (wh[0] - car.info.comx) - car.s * (wh[1] - car.info.comy);
          dust.push({ x: x, y: 0.05, vx: -Math.sign(car.vx) * (0.5 + rng() * 1.5) + car.vx * 0.15, vy: 0.3 + rng() * 1.1, r: 0.08 + rng() * 0.12, life: 0, max: 0.6 + rng(), a: 0.22, g: 0 });
        }
      }
    }
    if (S.running && dmg() > 0.5 && rng() < dt * 22 && dust.length < 700) {
      const hx = 1.4 * car.info.sx - car.info.comx, hy = 0.9 * car.info.sy - car.info.comy;
      dust.push({ x: car.x + car.c * hx - car.s * hy, y: car.y + car.s * hx + car.c * hy, vx: (rng() - 0.5) * 0.4 + car.vx * 0.05, vy: 0.9 + rng() * 0.8, r: 0.1, life: 0, max: 1.6 + rng(), a: 0.4, g: 0.5, smoke: true });
    }
  }
  function dmg() { const w = S.scene.world; return clamp(w.carImpulse / (w.car.mass * 14), 0, 1); }

  /* ---------- per-step bookkeeping ---------- */
  function afterStep() {
    const sc = S.scene, w = sc.world, car = sc.car;
    for (const ev of w.events) spawnImpact(ev);
    w.events.length = 0;
    const r = car.info.wr;
    if (!car.braking) car.spin += (car.vx * car.c + car.vy * car.s) * STEP / r;
    if (car.braking) {
      for (let i = 0; i < 2; i++) {
        const wh = car.info.wheels[i], lx = wh[0] - car.info.comx, ly = wh[1] - car.info.comy;
        const wx = car.x + car.c * lx - car.s * ly, wy = car.y + car.s * lx + car.c * ly;
        if (wy - r < 0.03 && Math.abs(car.vx) > 0.6) {
          const last = lastWheelX[i];
          if (last !== null && Math.abs(wx - last) < 1) {
            const sg = skids[skids.length - 1];
            if (sg && sg.w === i && Math.abs(sg.x1 - last) < 1e-6) sg.x1 = wx; else if (skids.length < 500) skids.push({ w: i, x0: last, x1: wx });
          }
