    }
    let mv = 0, mw = 0;
    for (const b of w.bodies) { const v = Math.abs(b.vx) + Math.abs(b.vy); if (v > mv) mv = v; const a = Math.abs(b.w); if (a > mw) mw = a; }
    if (w.hit) {
      S.still = (mv < 0.06 && mw < 0.12) ? S.still + STEP : 0;
      if (S.still >= 1.2 || w.time - w.hitTime > 45) finish();
    }
  }

  function brickStats() {
    const sc = S.scene, L = sc.P.layers; let moving = 0, disp = 0;
    for (const b of sc.bricks) {
      const sp = Math.abs(b.vx) + Math.abs(b.vy);
      if (sp > 0.15 || Math.abs(b.w) > 0.4) moving++;
      if (Math.abs(b.x - b.x0) > 0.12 || Math.abs(b.y - b.y0) > 0.12 || Math.abs(Math.atan2(b.s, b.c)) > 0.12) disp++;
    }
    return { moving: moving * L, disp: disp * L, total: sc.bricks.length * L };
  }

  function finish() {
    S.finished = true;
    const st = brickStats(), sc = S.scene, car = sc.car;
    const past = car.x + sc.P.carW / 2 - 0 - sc.wallX0;
    let far = 0; for (const b of sc.bricks) far = Math.max(far, b.x - sc.wallRight);
    setStatus('Complete', '');
    const standing = st.total - st.disp;
    showToast(`<b>Test complete</b> &middot; ${st.disp} of ${st.total} bricks displaced` + (standing > 0 ? `, ${standing} still standing` : ', wall destroyed') +
      ` &middot; car nose ended ${fmt(Math.abs(past), 1)} m ${past >= 0 ? 'past' : 'short of'} the wall face` + (far > 0.5 ? ` &middot; debris thrown ${fmt(far, 1)} m` : ''));
  }

  /* ---------- HUD ---------- */
  const el = { speed: $('#tSpeed'), time: $('#tTime'), moving: $('#tMoving'), disp: $('#tDisp'), mom: $('#tMom'), force: $('#tForce'), status: $('#status'), statusText: $('#statusText'), toast: $('#toast'), chips: $('#chips') };
  function setStatus(t, cls) { el.statusText.textContent = t; el.status.className = 'status ' + cls; }
  function showToast(html) { el.toast.innerHTML = html; el.toast.classList.add('show'); }
  function hideToast() { el.toast.classList.remove('show'); }
  function updateChips() {
    const items = [['', fmt(P.speed, 1), 'm/s'], ['Wall', `${P.cols}&times;${P.rows}&times;${P.layers}`, ''], ['Brick', fmt(P.brickMass, 1), 'kg'], ['Car', fmt(P.carMass, 0), 'kg'], ['g', fmt(P.gravity, 2), 'm/s²'], ['μ brick', fmt(P.brickFriction, 2), ''], ['e', fmt(P.brickRestitution, 2), ''], ['μ ground', fmt(P.groundFriction, 2), ''], ['Scale', fmt(P.scale, 0), 'px/m']];
    el.chips.innerHTML = items.map(([a, b, c]) => `<span class="chip">${a ? a + ' ' : ''}<b>${b}</b>${c ? ' ' + c : ''}</span>`).join('');
    $('#consts').innerHTML = [['Car size', `${fmt(P.carW, 1)} &times; ${fmt(P.carH, 2)} m`], ['Brick size', `${fmt(P.brickW, 2)} &times; ${fmt(P.brickH, 2)} m`], ['Bricks in wall', `${P.cols * P.rows * P.layers}`], ['Wall mass', `${fmt(P.cols * P.rows * P.layers * P.brickMass, 0)} kg`], ['Run-up', `${RUN_UP} m`], ['Physics step', '480 Hz']].map(([a, b]) => `<dt>${a}</dt><dd>${b}</dd>`).join('');
  }
  let hudT = 0;
  function updateHud(force) {
    const now = performance.now();
    if (!force && now - hudT < 66) return; hudT = now;
    const sc = S.scene, w = sc.world, car = sc.car, st = brickStats();
    const sp = Math.sqrt(car.vx * car.vx + car.vy * car.vy);
    el.speed.innerHTML = `${fmt(sp, 1)}<small>m/s &middot; ${fmt(sp * 3.6, 0)} km/h</small>`;
    el.time.innerHTML = `${fmt(w.time, 2)}<small>s</small>`;
    el.moving.innerHTML = `${st.moving}<small>/ ${st.total}</small>`;
    el.disp.innerHTML = `${st.disp}<small>/ ${st.total}</small>`;
    el.mom.innerHTML = `${fmt(car.mass * sp / 1000, 1)}<small>kN&middot;s</small>`;
    el.force.innerHTML = `${fmt(w.peakForce / 1000, 0)}<small>kN</small>`;
    if (S.running && !S.finished && w.hit) {
      const t = w.time - w.hitTime;
      if (t < 0.9) setStatus('Impact', 'hit'); else setStatus('Settling', 'run');
    }
  }

  /* ---------- camera ---------- */
  const xsBuf = { a: new Float64Array(1) };
  function updateCamera(dt) {
    const sc = S.scene, car = sc.car;
    let tx = base.x, ts = base.s;
    if (S.running && sc.world.hit) {
      const n = sc.bricks.length;
      if (xsBuf.a.length !== n) xsBuf.a = new Float64Array(n);
      for (let i = 0; i < n; i++) xsBuf.a[i] = sc.bricks[i].x;
      xsBuf.a.sort();
      const p04 = xsBuf.a[Math.floor(0.04 * (n - 1))], p96 = xsBuf.a[Math.floor(0.96 * (n - 1))];
      const hl = sc.P.carW / 2;
      const lo = Math.min(car.x - hl - 1.5, p04 - 1.5, sc.wallX0 - 2.5), hi = Math.max(car.x + hl + 1.5, p96 + 1.5, sc.wallRight + 1);
      const width = hi - lo;
      ts = clamp((W - 24) / width, 22, base.s);
      const vis = (W - 24) / ts;
      if (width > vis) { tx = lo + vis / 2; const carHi = car.x + hl + 1.5; if (carHi > lo + vis) tx = carHi - vis / 2; }
      else tx = (lo + hi) / 2;
    }
    const k = 1 - Math.exp(-dt * 3.2);
    cam.x += (tx - cam.x) * k;
    cam.s = Math.exp(Math.log(cam.s) + (Math.log(ts) - Math.log(cam.s)) * k);
  }

  /* ---------- rendering ---------- */
  const BRICK = ['#b9583d', '#ad4f38', '#c4694c', '#a24833', '#bd6042', '#a64c34'];
  const BACK = ['#8a3f2d', '#753526', '#642d20', '#552619'];
  let sky = null;
  function buildSky() {
    sky = ctx.createLinearGradient(0, 0, 0, groundY);
    sky.addColorStop(0, '#8fb9de'); sky.addColorStop(0.55, '#c9def0'); sky.addColorStop(1, '#f2ead9');
  }
  function drawHills(par, lift, amp, freq, color) {
    ctx.beginPath(); ctx.moveTo(0, groundY);
    for (let x = 0; x <= W + 12; x += 12) {
      const t = (x + cam.x * cam.s * par) / freq;
      ctx.lineTo(x, groundY - lift - amp * (Math.sin(t * 1.3) + 0.6 * Math.sin(t * 2.9 + 1.7) + 0.3 * Math.sin(t * 6.1 + 0.4)));
    }
    ctx.lineTo(W, groundY); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
  }

  function render() {
    const sc = S.scene, world = sc.world, car = sc.car, Sc = cam.s;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    simT += 0.016;
    const shx = shake.amp * Math.sin(simT * 83) , shy = shake.amp * 0.6 * Math.sin(simT * 97 + 1);
    ctx.fillStyle = sky; ctx.fillRect(0, 0, W, groundY + 2);
    const sun = ctx.createRadialGradient(W * 0.78, groundY * 0.28, 4, W * 0.78, groundY * 0.28, 170);
    sun.addColorStop(0, 'rgba(255,248,224,.85)'); sun.addColorStop(1, 'rgba(255,248,224,0)');
    ctx.fillStyle = sun; ctx.fillRect(0, 0, W, groundY);
    drawHills(0.05, 70, 26, 260, '#b6cddb'); drawHills(0.12, 26, 20, 170, '#9db9ca'); drawHills(0.22, 0, 12, 110, '#85a3b5');

    const ox = W / 2 - cam.x * Sc + shx, oy = groundY + shy;
    const xl = cam.x - (W / 2 + 60) / Sc, xr = cam.x + (W / 2 + 60) / Sc;

    /* lamp posts + fence (world fixed) */
    ctx.lineWidth = Math.max(1.5, 0.07 * Sc); ctx.strokeStyle = '#5c6b78';
    for (let x = Math.ceil(xl / 12) * 12; x < xr; x += 12) {
      const X = ox + x * Sc; ctx.beginPath(); ctx.moveTo(X, oy); ctx.lineTo(X, oy - 5.6 * Sc); ctx.lineTo(X + 0.9 * Sc, oy - 5.9 * Sc); ctx.stroke();
      ctx.fillStyle = '#fff6d0'; ctx.fillRect(X + 0.75 * Sc, oy - 5.95 * Sc, 0.4 * Sc, 0.09 * Sc);
    }
    ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(70,84,96,.55)';
    ctx.beginPath(); ctx.moveTo(0, oy - 0.75 * Sc); ctx.lineTo(W, oy - 0.75 * Sc); ctx.moveTo(0, oy - 0.35 * Sc); ctx.lineTo(W, oy - 0.35 * Sc);
    for (let x = Math.ceil(xl / 2) * 2; x < xr; x += 2) { const X = ox + x * Sc; ctx.moveTo(X, oy); ctx.lineTo(X, oy - 0.95 * Sc); }
    ctx.stroke();

    /* ground */
    const gg = ctx.createLinearGradient(0, groundY, 0, H);
    gg.addColorStop(0, '#565c66'); gg.addColorStop(0.08, '#3c4149'); gg.addColorStop(1, '#22262c');
    ctx.fillStyle = gg; ctx.fillRect(0, oy, W, H - oy + 4);
    ctx.fillStyle = '#9aa1ab'; ctx.fillRect(0, oy, W, Math.max(3, 0.07 * Sc));
    ctx.fillStyle = 'rgba(226,226,210,.72)';
    const dashY = oy + Math.max(22, 0.42 * Sc);
    for (let x = Math.floor(xl / 3) * 3; x < xr; x += 3) ctx.fillRect(ox + x * Sc, dashY, 1.4 * Sc, Math.max(2, 0.05 * Sc));
    ctx.font = '600 11px ui-sans-serif,system-ui,sans-serif'; ctx.textAlign = 'center';
    for (let x = Math.ceil(xl / 5) * 5; x < xr; x += 5) {
      const X = ox + x * Sc;
      ctx.fillStyle = '#ffcf5a'; ctx.fillRect(X - 1, oy, 2, Math.max(6, 0.12 * Sc) + 5);
      ctx.fillStyle = 'rgba(255,255,255,.7)'; ctx.fillText(x + ' m', X, oy + Math.max(22, 0.42 * Sc) + 24);
    }
    ctx.fillStyle = 'rgba(255,255,255,.14)';
    for (let x = Math.ceil(xl); x < xr; x++) if (x % 5) ctx.fillRect(ox + x * Sc, oy, 1, 4);
    /* skid marks */
    ctx.fillStyle = 'rgba(8,8,10,.62)';
    const sh = Math.max(2, 0.05 * Sc);
    for (const s of skids) ctx.fillRect(ox + Math.min(s.x0, s.x1) * Sc, oy + 1 + s.w * 3, Math.abs(s.x1 - s.x0) * Sc + 1, sh);

    /* back layers of wall */
    const bricks = sc.bricks, nB = bricks.length, L = sc.P.layers, bw = sc.P.brickW / 2, bh = sc.P.brickH / 2;
    const cx = new Float32Array(nB * 8);
    for (let i = 0; i < nB; i++) {
      const b = bricks[i], c = b.c, s = b.s, o = i * 8;
      const ax = c * bw, ay = s * bw, bx = -s * bh, by = c * bh;
      cx[o] = ox + (b.x - ax - bx) * Sc; cx[o + 1] = oy - (b.y - ay - by) * Sc;
      cx[o + 2] = ox + (b.x + ax - bx) * Sc; cx[o + 3] = oy - (b.y + ay - by) * Sc;
      cx[o + 4] = ox + (b.x + ax + bx) * Sc; cx[o + 5] = oy - (b.y + ay + by) * Sc;
      cx[o + 6] = ox + (b.x - ax + bx) * Sc; cx[o + 7] = oy - (b.y - ay + by) * Sc;
    }
    const inside = (i) => cx[i * 8] > -80 && cx[i * 8] < W + 80;
    ctx.lineJoin = 'round';
    for (let l = L - 1; l >= 1; l--) {
      const dx = l * 0.05 * Sc, dy = -l * 0.035 * Sc;
