      }
      ctx.fillStyle = BACK[Math.min(l - 1, 3)]; ctx.fill();
      ctx.strokeStyle = 'rgba(28,10,6,.55)'; ctx.lineWidth = 1; ctx.stroke();
    }
    /* front layer */
    for (let t = 0; t < 6; t++) {
      ctx.beginPath(); let any = false;
      for (let i = 0; i < nB; i++) {
