        ctx.moveTo(cx[o], cx[o + 1]); ctx.lineTo(cx[o + 2], cx[o + 3]); ctx.lineTo(cx[o + 4], cx[o + 5]); ctx.lineTo(cx[o + 6], cx[o + 7]); ctx.closePath();
      }
      if (any) { ctx.fillStyle = BRICK[t]; ctx.fill(); }
    }
    ctx.beginPath();
    for (let i = 0; i < nB; i++) { if (!inside(i)) continue; const o = i * 8; ctx.moveTo(cx[o + 6], cx[o + 7]); ctx.lineTo(cx[o + 4], cx[o + 5]); }
    ctx.strokeStyle = 'rgba(255,214,190,.30)'; ctx.lineWidth = Math.max(1, 0.03 * Sc); ctx.stroke();
    ctx.beginPath();
    for (let i = 0; i < nB; i++) {
      if (!inside(i)) continue; const o = i * 8;
      ctx.moveTo(cx[o], cx[o + 1]); ctx.lineTo(cx[o + 2], cx[o + 3]); ctx.lineTo(cx[o + 4], cx[o + 5]); ctx.lineTo(cx[o + 6], cx[o + 7]); ctx.closePath();
    }
    ctx.strokeStyle = 'rgba(52,20,12,.6)'; ctx.lineWidth = 1; ctx.stroke();

    /* dust behind car, then car, chips, smoke */
    drawParticles(ox, oy, Sc, false);
    drawCar(car, ox, oy, Sc);
    drawParticles(ox, oy, Sc, true);
    ctx.textAlign = 'left';
  }

  function drawParticles(ox, oy, Sc, front) {
    if (front) {
      for (const p of chips) {
        const a = 1 - Math.max(0, (p.life - p.max * 0.7) / (p.max * 0.3));
        ctx.save(); ctx.translate(ox + p.x * Sc, oy - p.y * Sc); ctx.rotate(-p.rot); ctx.globalAlpha = a;
        ctx.fillStyle = BRICK[p.tint]; const s = Math.max(1.5, p.sz * Sc); ctx.fillRect(-s, -s * 0.6, s * 2, s * 1.2); ctx.restore();
      }
      ctx.globalAlpha = 1;
    } else {
      for (const p of dust) {
        const t = p.life / p.max, a = p.a * (1 - t) * (t < 0.1 ? t / 0.1 : 1);
        ctx.fillStyle = p.smoke ? `rgba(45,45,50,${a * 1.3})` : `rgba(176,158,136,${a})`;
        ctx.beginPath(); ctx.arc(ox + p.x * Sc, oy - p.y * Sc, Math.max(1, p.r * Sc), 0, 6.2832); ctx.fill();
      }
    }
  }

  function drawCar(car, ox, oy, Sc) {
    const inf = car.info, sx = inf.sx, sy = inf.sy, comx = inf.comx, comy = inf.comy;
    const gx = (x) => x * sx - comx, gy = (y) => y * sy - comy;
