    const hgt = Math.max(0, car.y - comy);
    ctx.save();
    ctx.fillStyle = `rgba(10,12,16,${0.30 * Math.exp(-hgt * 1.4)})`;
    ctx.beginPath(); ctx.ellipse(ox + car.x * Sc, oy + 1, car.info.sx * 2.1 * Sc, 5 + 0.06 * Sc, 0, 0, 6.2832); ctx.fill();
    ctx.translate(ox + car.x * Sc, oy - car.y * Sc); ctx.rotate(-Math.atan2(car.s, car.c)); ctx.scale(Sc, -Sc);
    ctx.lineJoin = 'round';
    /* body */
    const chassis = car.shapes[0], cabin = car.shapes[1];
    const poly = (sh) => { ctx.beginPath(); ctx.moveTo(sh.lx[0], sh.ly[0]); for (let i = 1; i < sh.n; i++) ctx.lineTo(sh.lx[i], sh.ly[i]); ctx.closePath(); };
    let g = ctx.createLinearGradient(0, gy(0.28), 0, gy(0.86)); g.addColorStop(0, '#173a9c'); g.addColorStop(0.55, '#2c66f0'); g.addColorStop(1, '#5f93ff');
    poly(chassis); ctx.fillStyle = g; ctx.fill(); ctx.strokeStyle = '#0d2270'; ctx.lineWidth = 1.6 * lw; ctx.stroke();
    g = ctx.createLinearGradient(0, gy(0.8), 0, gy(1.45)); g.addColorStop(0, '#3b76f7'); g.addColorStop(1, '#7ea9ff');
    poly(cabin); ctx.fillStyle = g; ctx.fill(); ctx.strokeStyle = '#0d2270'; ctx.stroke();
    /* windows */
    const glass = ctx.createLinearGradient(0, gy(0.88), 0, gy(1.4)); glass.addColorStop(0, '#26364f'); glass.addColorStop(1, '#8fb4d6');
    ctx.fillStyle = glass;
    ctx.beginPath(); ctx.moveTo(gx(0.72), gy(0.88)); ctx.lineTo(gx(0.28), gy(1.36)); ctx.lineTo(gx(-0.20), gy(1.36)); ctx.lineTo(gx(-0.20), gy(0.88)); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(gx(-0.30), gy(0.88)); ctx.lineTo(gx(-0.30), gy(1.36)); ctx.lineTo(gx(-0.80), gy(1.36)); ctx.lineTo(gx(-1.15), gy(0.88)); ctx.closePath(); ctx.fill();
    /* crash-test dummy */
    ctx.fillStyle = '#f6c21e'; ctx.beginPath(); ctx.arc(gx(-0.02), gy(1.12), 0.17 * Math.min(sx, sy), 0, 6.2832); ctx.fill();
    ctx.fillStyle = '#151515'; ctx.beginPath(); ctx.moveTo(gx(-0.02), gy(1.12)); ctx.arc(gx(-0.02), gy(1.12), 0.17 * Math.min(sx, sy), 0, 1.5708); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(gx(-0.02), gy(1.12)); ctx.arc(gx(-0.02), gy(1.12), 0.17 * Math.min(sx, sy), 3.1416, 4.7124); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(20,30,50,.5)'; ctx.fillRect(gx(-0.12), gy(0.88), 0.2 * sx, 0.16 * sy);
    /* damage: cracks */
    const d = dmg();
    if (d > 0.12) {
