        `<input type="range" id="rg-${d.key}" min="${d.min}" max="${d.max}" step="${d.step}">`;
      (d.main ? $('#mainCtl') : $('#advCtl')).appendChild(wrap);
      const rg = wrap.querySelector('input[type=range]'), nm = wrap.querySelector('input[type=number]');
      inputs[d.key] = { rg, nm, d };
      rg.addEventListener('input', () => setParam(d.key, parseFloat(rg.value)));
      nm.addEventListener('change', () => { const v = parseFloat(nm.value); setParam(d.key, isNaN(v) ? DEFAULTS[d.key] : v); });
      nm.addEventListener('keydown', (e) => { if (e.key === 'Enter') nm.blur(); });
    }
    syncInputs();
  }
  function syncInputs() {
    for (const k in inputs) {
      const { rg, nm, d } = inputs[k], v = P[k];
      rg.value = v; nm.value = v.toFixed(d.dec);
