  function resize() {
    const r = stage.getBoundingClientRect();
    W = Math.max(280, r.width); H = Math.max(280, r.height); dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    groundY = Math.max(H * 0.5, Math.min(H * 0.76, H - 150));
