  buildPanel(); resize(); build();

  /* ---------- main loop ---------- */
  let last = performance.now();
  function frame(now) {
    const dt = Math.min(0.05, Math.max(0, (now - last) / 1000)); last = now;
    let fxDt = dt;
    if (S.running && !S.finished) {
      S.acc += dt * S.timeScale; let n = 0;
      while (S.acc >= STEP && n < 6) { S.scene.world.step(); afterStep(); S.acc -= STEP; n++; if (S.finished) break; }
      if (n === 6) S.acc = 0;
